class Solution {
  public int numKLenSubstrNoRepeats(String s, int k) {
    if (k > 26) return 0;
    int[] count = new int[26];
    int total = 0;
    for (int left = 0, right = 0; right < s.length(); right++) {
      char c = s.charAt(right);
      count[c - 'a']++;
      while (count[c - 'a'] > 1 || right - left + 1 > k) count[s.charAt(left++) - 'a']--;
      if (right - left + 1 == k) total++;
    }
    return total;
  }
}
